pre.code:
:root {
  --theme-name: "我的主题";
  --theme-description: "宋体正文，适合长篇阅读";
  --theme-base: craft;
  --accent: hsl(212, 70%, 45%);
}

.page { font-family: "Songti SC", serif; font-size: 17px; line-height: 1.8; max-width: 680px; }
h1 { font-size: 1.6em; font-weight: 700; margin-top: 40px; }
a { color: var(--accent); text-decoration: underline; }
blockquote { border-left: 3px solid var(--accent); font-style: italic; }
hr { border-top: 1px solid #d0d0d0; }
